@startuml

class User {
  + ID : int
  + Name : string
  + Email : string
  + DateOfBirth : date
}

class Account {
  + AccountNumber : int
}

class PersonalAccount extends Account {}

class BusinessAccount extends Account {
  + CompanyName : string
  + MonthlyFee : float
}

class Page {
  + PageName : string
  + NumberOfVisits : int
}

class AdvertisementPage extends Page {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

User "1" -- "0..1" Account : owns
Account "1" -- "*" Page : administrates
PersonalAccount "0..1" -- "*" Page : granted privileges to
PersonalAccount "1" -- "*" PersonalAccount : sends/receives friend requests

@enduml

